export type DocumentationEmailDetail = {
  label: string;
  value: string;
};

export type DocumentationEmailBlock =
  | { type: 'paragraph'; text: string }
  | { type: 'heading'; text: string }
  | { type: 'details'; items: DocumentationEmailDetail[] }
  | { type: 'list'; items: string[] }
  | { type: 'link'; label: string; before?: string; after?: string }
  | { type: 'button'; label: string }
  | { type: 'notice'; text: string }
  | { type: 'signature'; lines: string[] };

export type DocumentationEmailSample = {
  title: string;
  subject: string;
  blocks: DocumentationEmailBlock[];
};

export const documentationEmailSamplesText = (samples?: DocumentationEmailSample[]): string =>
  (samples || [])
    .flatMap((sample) => [
      sample.title,
      sample.subject,
      ...sample.blocks.flatMap((block) => {
        if ('text' in block) return [block.text];
        if (block.type === 'details') return block.items.flatMap((item) => [item.label, item.value]);
        if (block.type === 'list') return block.items;
        if (block.type === 'signature') return block.lines;
        if (block.type === 'link') return [block.before || '', block.label, block.after || ''];
        if (block.type === 'button') return [block.label];
        return [];
      }),
    ])
    .join(' ');

export type DocumentationSection = {
  id: string;
  kicker: string;
  title: string;
  summary: string;
  body: string[];
  emailSamples?: DocumentationEmailSample[];
  bullets?: string[];
  callout?: string;
  defaultOpen?: boolean;
  searchTerms?: string[];
  Unpublished_Internal_Notes?: string[];
  Unpublished_Related_Repos?: string[];
};

export type DocumentationChapter = {
  id: string;
  kicker: string;
  title: string;
  summary: string;
  sections: DocumentationSection[];
  defaultOpen?: boolean;
  searchTerms?: string[];
  Unpublished_Internal_Notes?: string[];
  Unpublished_Related_Repos?: string[];
};

